def isCircle(N, A):
    # Create a graph where each character is a node
    # and there is a directed edge from node u to node v
    # if the last character of string u is the same as the first character of string v
    graph = {}
    in_degree = {}
    out_degree = {}

    for s in A:
        u = s[0]
        v = s[-1]
        if u not in graph:
            graph[u] = []
