            out_degree[u] = 0
        if v not in graph:
            graph[v] = []
            in_degree[v] = 0
            out_degree[v] = 0
        graph[u].append(v)
        out_degree[u] += 1
        in_degree[v] += 1

    # For the graph to be eulerian, all non-zero degree vertices must be connected
    # and in_degree == out_degree for every vertex with non-zero degree
    start_nodes = 0
    end_nodes = 0
    for node in graph:
        if in_degree[node] != out_degree[node]:
            if in_degree[node] == out_degree[node] + 1:
                end_nodes += 1
            elif in_degree[node] + 1 == out_degree[node]:
                start_nodes += 1
            else:
                return 0

    # There should be at most one vertex with (out_degree - in_degree == 1)
    # and at most one vertex with (in_degree - out_degree == 1)
    # and all other vertices should have equal in_degree and out_degree
    if not ((start_nodes == 0 and end_nodes == 0) or (start_nodes == 1 and end_nodes == 1)):
        return 0

